Create database customer_behaviour;
USE customer_behaviour;

#Overview the data
SELECT * FROM customer limit 8;

#--Q1: What is the total revenue generated by male vs female customer?
SELECT gender, SUM(purchase_amount) as total_revenue
FROM customer
GROUP BY gender;

#--Q2: Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id,purchase_amount
FROM customer
WHERE discount_applied="Yes" and purchase_amount >= (SELECT AVG(purchase_amount) FROM customer);   #SUBQUERY used

#This is the code to check avg 
select avg(purchase_amount) as av FROM customer;

#--Q3: Which are the top 5 products with the highest average review rating?
SELECT item_purchased,ROUND(AVG(review_rating),2) as "Avg Product Ratimg"
FROM customer
GROUP BY item_purchased
ORDER BY avg(review_rating) DESC
LIMIT 5;

#--Q4: Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT shipping_type, Round(AVG(purchase_amount),2) as "Avg Purchase Amount"
FROM customer
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type;

#--Q5: Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers?
SELECT subscription_status,
COUNT(customer_id) as 'Total Customers',
ROUND(AVG(purchase_amount),2) as AVG_SPEND,
ROUND(SUM(purchase_amount),2) as Total_Revenue
FROM customer
GROUP BY subscription_status
ORDER BY Total_Revenue,AVG_SPEND DESC;

#--Q6: Which 5 products have the highest percentage of purchase with discount applied?
SELECT item_purchased,
ROUND(100* SUM(CASE WHEN discount_applied='Yes' THEN 1 ELSE 0 END)/COUNT(*),2) as discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

#--Q7: Segment customers into New, Returning, and Loyal based on their total number of previous purchase and show the count of each segment?
WITH customer_type as (SELECT customer_id,previous_purchases,
CASE																				
	WHEN previous_purchases=1 THEN 'NEW'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer)                                   
SELECT customer_segment, count(*) as "NO. OF CUSTOMERS"
FROM customer_type
GROUP BY customer_segment;
    
#--Q8: What are the top 3 most purchased products  in each category?
WITH item_counts as (
SELECT category,item_purchased,
COUNT(customer_id) as Total_orders,
ROW_NUMBER() OVER(PARTITION BY category ORDER BY count(customer_id) DESC) as item_rank
FROM customer
GROUP BY category,item_purchased)
SELECT item_rank,category,item_purchased,total_orders
FROM item_counts
WHERE item_rank <=3;

#--Q9:Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
COUNT(customer_id) as repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

#--Q10:What is the reveune contribution of each group?
SELECT age_group,
SUM(purchase_amount) as total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;

